import { useVirtualizer } from '@tanstack/react-virtual';
import React from 'react';
import type { TableInstance } from 'react-table';

import type { DataTableContentProps } from './DataTableContent.js';
import { DataTableRow } from './DataTableRow.js';
import type { DataTableSlots } from '../hooks/useDataTableSlots.js';
import { ExpandableRowWrapper } from '../plugins/use-expandable-row/ExpandableRowWrapper.js';

type DataTableVirtualizedContentProps = {
  rowVirtualizer: ReturnType<typeof useVirtualizer>;
  columnVirtualizer: ReturnType<typeof useVirtualizer>;
  columnVirtualization: boolean;
  expandedRowOffsets: number[];
  tableContainerRef: React.RefObject<HTMLDivElement>;
  isGridLayout: boolean;
} & Pick<TableInstance, 'prepareRow' | 'page' | 'dispatch'> &
  Pick<DataTableContentProps, 'tableVariant' | 'userActions' | 'lineWrap'> &
  Pick<DataTableSlots, 'expandableRowTemplate'>;

export function DataTableVirtualizedContent(
  props: DataTableVirtualizedContentProps,
) {
  const {
    rowVirtualizer,
    columnVirtualizer,
    columnVirtualization,
    expandableRowTemplate,
    expandedRowOffsets,
    page,
    prepareRow,
    userActions,
    lineWrap,
    tableVariant,
    dispatch,
    tableContainerRef,
    isGridLayout,
  } = props;

  return rowVirtualizer.getVirtualItems().map((virtualRow) => {
    const expandedRowOffset = expandedRowOffsets.at(virtualRow.index);
    if (expandedRowOffset === undefined) {
      return null;
    }
    // the first overall row on a page can never be an expandable row
    // but if the value from the current virtual index to the prev changed
    // we know that the element must be the expandable part of the row
    // we want to render this part even if the actual data row is not rendered to avoid
    // any jumping or strange offsets.
    const indexRendersExpandable =
      virtualRow.index !== 0 &&
      expandedRowOffsets.at(virtualRow.index) !==
        expandedRowOffsets.at(virtualRow.index - 1);

    const indexOfDataRow = virtualRow.index - expandedRowOffset;
    const dataRow = page.at(indexOfDataRow);
    if (!dataRow) {
      return null;
    }

    if (indexRendersExpandable && expandableRowTemplate !== null) {
      return (
        <ExpandableRowWrapper
          key={`expandable-${virtualRow.key}`}
          virtualRow={virtualRow}
          row={dataRow}
          render={expandableRowTemplate}
          data-index={virtualRow.index}
          rowVirtualizerMeasureElement={rowVirtualizer.measureElement}
        />
      );
    }

    prepareRow(dataRow);

    const {
      style: rowStyle,
      key,
      ...remainingRowProps
    } = dataRow.getRowProps();

    return (
      <DataTableRow
        key={virtualRow.key}
        rowProps={remainingRowProps}
        rowStyle={rowStyle}
        pageRow={dataRow}
        virtualRow={virtualRow}
        columnVirtualizer={columnVirtualizer}
        columnVirtualization={columnVirtualization}
        lineWrap={lineWrap}
        fontStyle={
          tableVariant.fontStyle === undefined ? 'text' : tableVariant.fontStyle
        }
        userActions={userActions}
        dispatch={dispatch}
        index={indexOfDataRow}
        tableContainerRef={tableContainerRef}
        rowVirtualizerMeasureElement={rowVirtualizer.measureElement}
        isGridLayout={isGridLayout}
      />
    );
  });
}
